import {assistantEndpoint} from './ai-config.js?v=19';
import {BrowserAI,LOCAL_PROFILES} from './local-ai.js?v=20';
export class LabAssistant{
 constructor({getContext,capture,prepareAI,localAI,endpoint=assistantEndpoint,document=globalThis.document,fetcher=globalThis.fetch}={}){
  Object.assign(this,{document,getContext,capture,endpoint,fetcher,threads:new Map(),drafts:new Map(),busy:false,attachments:[],preparing:0});
  this.local=!endpoint;this.localAI=localAI||new BrowserAI();this.prepareAI=prepareAI;this.selectedProfile='balanced';this.loading=false;
  this.root=document.createElement('aside');this.root.id='aiAssistant';this.root.className='ai-assistant';this.root.hidden=true;this.root.setAttribute('aria-labelledby','aiTitle');
  this.root.innerHTML='<div class="ai-head"><h2 id="aiTitle">Trợ lý Vật lí</h2><div><button type="button" data-ai="expand" aria-label="Mở rộng trợ lý" aria-pressed="false">↗</button><button type="button" data-ai="close" aria-label="Đóng trợ lý">×</button></div></div><p class="ai-status" role="status" aria-live="polite"></p><section class="ai-local-setup"><label for="aiModel">AI trên thiết bị</label><select id="aiModel"></select><p class="ai-model-note"></p><div class="ai-load-actions"><button type="button" data-ai="load">Tải AI</button><button type="button" data-ai="unload" hidden>Giải phóng bộ nhớ</button></div><progress max="1" value="0" hidden aria-label="Tiến độ tải AI"></progress></section><div class="ai-messages" role="log" aria-label="Hội thoại"></div><form class="ai-compose"><label for="aiQuestion">Câu hỏi của bạn</label><textarea id="aiQuestion" maxlength="1600" placeholder="Hỏi về hiện tượng, số liệu hoặc gửi ảnh…"></textarea><div class="ai-attachments" aria-label="Ảnh sắp gửi"></div><p class="ai-image-note"></p><div class="ai-tools"><button type="button" data-ai="attach">＋ Thêm ảnh</button><button type="button" data-ai="capture">Chụp mô hình</button><input type="file" id="aiImage" accept="image/png,image/jpeg,image/webp" multiple hidden></div><label class="ai-consent"><input type="checkbox" id="aiContext">Dùng thông số và các dòng đo gần nhất</label><details><summary>Xem dữ liệu gửi kèm</summary><pre class="ai-context"></pre><p><span class="ai-privacy"></span> Hội thoại được giữ trong bộ nhớ của trang, không lưu sau khi tải lại.</p></details><div class="ai-actions"><button type="button" data-ai="clear">Hội thoại mới</button><button type="button" data-ai="cancel" hidden>Dừng</button><button type="submit">Gửi ↑</button></div></form>';
  document.body.append(this.root);this.q=s=>this.root.querySelector(s);this.status=this.q('.ai-status');this.form=this.q('form');this.input=this.q('textarea');this.input.setAttribute('maxlength',this.local?'1600':'6000');this.submit=this.q('[type=submit]');
  this.q('#aiContext').checked=this.local;this.q('.ai-local-setup').hidden=!this.local;this.q('#aiModel').innerHTML=LOCAL_PROFILES.map(p=>`<option value="${p.id}"${p.id===this.selectedProfile?' selected':''}>${p.label}</option>`).join('');this.q('#aiModel').addEventListener('change',()=>{if(this.busy||this.loading)return;this.selectedProfile=this.q('#aiModel').value;this.localAI.dispose();this.render();});this.q('[data-ai=load]').addEventListener('click',()=>this.loadAI());this.q('[data-ai=unload]').addEventListener('click',()=>{this.localAI.dispose();this.render();this.status.textContent='Đã giải phóng bộ nhớ GPU. Hội thoại vẫn được giữ.';});
  this.openButton=document.querySelector('#openAssistant');this.openButton?.addEventListener('click',()=>this.open());
  this.q('[data-ai=close]').addEventListener('click',()=>this.close());this.q('[data-ai=expand]').addEventListener('click',e=>{const wide=this.root.classList.toggle('ai-wide');e.currentTarget.setAttribute('aria-pressed',String(wide));e.currentTarget.setAttribute('aria-label',wide?'Thu gọn trợ lý':'Mở rộng trợ lý');});
  this.q('[data-ai=cancel]').addEventListener('click',()=>this.controller?.abort());this.q('[data-ai=clear]').addEventListener('click',()=>{if(this.busy||this.loading)return;this.threads.delete(this.key());this.input.value='';this.attachments=[];this.render();});
  this.q('[data-ai=attach]').addEventListener('click',()=>this.q('#aiImage').click());this.q('#aiImage').addEventListener('change',async e=>{await this.addFiles([...e.target.files]);e.target.value='';});
  this.q('[data-ai=capture]').addEventListener('click',()=>this.captureModel());
  this.input.addEventListener('paste',e=>{const files=[...(e.clipboardData?.files||[])];if(files.length){e.preventDefault();this.addFiles(files);}});
  this.root.addEventListener('dragover',e=>{if(e.dataTransfer?.types?.includes('Files'))e.preventDefault();});this.root.addEventListener('drop',e=>{if(e.dataTransfer?.files?.length){e.preventDefault();this.addFiles([...e.dataTransfer.files]);}});
  this.form.addEventListener('submit',e=>{e.preventDefault();this.send();});this.input.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();this.send();}});this.root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();this.close();}});this.render();
 }
 key(){return this.getContext?.()?.id||'library';}
 thread(key=this.key()){if(!this.threads.has(key))this.threads.set(key,[]);return this.threads.get(key);}
 refreshContext(){if(this.root.hidden)return;if(this.currentKey!==this.key())this.render();else this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{},null,2);this.q('[data-ai=capture]').disabled=!this.capture||this.key()==='library'||this.busy||this.loading||(this.local&&!this.visionEnabled());}
 open(){this.root.hidden=false;this.openButton?.setAttribute('aria-expanded','true');this.render();this.input.focus();}
 close(){this.root.hidden=true;this.openButton?.setAttribute('aria-expanded','false');this.openButton?.focus();}
 visionEnabled(){return LOCAL_PROFILES.find(p=>p.id===this.selectedProfile)?.vision;}
 render(){const key=this.key();if(this.currentKey&&this.currentKey!==key){this.drafts.set(this.currentKey,{text:this.input.value,attachments:this.attachments});const draft=this.drafts.get(key);this.input.value=draft?.text||'';this.attachments=draft?.attachments||[];}this.currentKey=key;
  const list=this.q('.ai-messages');list.setAttribute('aria-live',this.busy?'off':'polite');list.replaceChildren();for(const message of [...this.thread(),...(this.streaming&&this.streaming.key===key?[{role:'user',content:this.streaming.question,images:this.streaming.images},{role:'assistant',content:this.streaming.content||'…'}]:[])]){const el=this.document.createElement('div');el.className='ai-message';el.dataset.role=message.role;const label=this.document.createElement('b');label.textContent=message.role==='user'?'Bạn':'Trợ lý AI';el.append(label,this.document.createTextNode(message.content));for(const src of message.images||[]){const img=this.document.createElement('img');img.src=src;img.alt='Ảnh đã gửi';el.append(img);}list.append(el);}if(!this.thread().length&&!this.streaming){const el=this.document.createElement('p');el.className='ai-empty';el.textContent=this.local?'Hỏi về bài đang mở. Câu trả lời xuất hiện ngay tại đây.':'Gửi câu hỏi hoặc ảnh. Bạn có thể hỏi tiếp để hiểu rõ cách giải.';list.append(el);}list.scrollTop=list.scrollHeight;
  const previews=this.q('.ai-attachments');previews.replaceChildren();this.attachments.forEach((attachment,index)=>{const wrap=this.document.createElement('div'),img=this.document.createElement('img'),remove=this.document.createElement('button');img.src=attachment.url;img.alt=attachment.name;remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Xóa ảnh '+attachment.name);remove.disabled=this.busy;remove.addEventListener('click',()=>{this.attachments.splice(index,1);this.render();});wrap.append(img,remove);previews.append(wrap);});
  this.q('.ai-image-note').textContent=this.local&&!this.visionEnabled()?'Để gửi ảnh, chọn mô hình Có ảnh.':'';this.q('.ai-image-note').hidden=!this.local||this.visionEnabled();this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{},null,2);this.submit.disabled=this.busy||this.loading||this.preparing>0||(this.local?!this.localAI.engine:!this.endpoint);this.q('[data-ai=cancel]').hidden=!this.busy&&!this.loading;for(const name of ['clear','attach'])this.q('[data-ai='+name+']').disabled=this.busy||this.loading||this.preparing>0||(name==='attach'&&this.local&&!this.visionEnabled());this.q('[data-ai=capture]').disabled=this.busy||this.loading||this.preparing>0||!this.capture||key==='library'||(this.local&&!this.visionEnabled());this.q('#aiModel').disabled=this.busy||this.loading||this.preparing>0;this.q('[data-ai=load]').disabled=this.busy||this.loading||!this.localAI.supported;this.q('[data-ai=load]').textContent=this.localAI.engine?'Tải lại AI':'Tải AI';this.q('[data-ai=unload]').hidden=!this.localAI.engine||this.busy||this.loading;this.q('progress').hidden=!this.loading;this.q('.ai-model-note').textContent=LOCAL_PROFILES.find(p=>p.id===this.selectedProfile)?.memory||'';this.q('.ai-privacy').textContent=this.local?'Suy luận trên thiết bị. Lần đầu cần tải mô hình từ Hugging Face và MLC; câu hỏi và ảnh không gửi tới dịch vụ AI.':'Ảnh và dữ liệu chỉ gửi tới OpenAI khi bạn nhấn Gửi.';this.status.textContent=this.loading?'Đang tải AI…':this.preparing?'Đang chuẩn bị ảnh…':this.busy?'Đang trả lời…':this.local?(!this.localAI.supported?'Trình duyệt chưa có WebGPU; chatbot chưa chạy được trên thiết bị này.':this.localAI.engine?'AI sẵn sàng · Hãy đối chiếu công thức và số liệu.':'Tải AI để bắt đầu. Lần đầu có thể mất vài phút và tốn dung lượng mạng.'):'AI có thể nhầm. Hãy đối chiếu công thức và số liệu.';

 }
 async loadAI(){if(this.loading||this.busy)return;this.loading=true;this.controller=new AbortController();this.render();this.q('progress').value=0;let error='';try{this.prepareAI?.();await this.localAI.load(this.selectedProfile,{signal:this.controller.signal,onProgress:p=>{this.q('progress').value=Math.max(0,Math.min(1,Number(p.progress)||0));this.status.textContent='Đang tải AI · '+Math.round(this.q('progress').value*100)+'%';}});}catch(e){error=e.name==='AbortError'?'Đã dừng tải AI. Bạn có thể tải lại khi cần.':e.message;}finally{this.loading=false;this.controller=null;this.render();if(error)this.status.textContent=error;}}
 async sendLocal(){const question=this.input.value.trim();if((!question&&!this.attachments.length)||this.busy||this.loading||this.preparing)return;if(!this.localAI.engine){this.status.textContent=this.localAI.supported?'Hãy tải AI trước khi gửi câu hỏi.':'Trình duyệt chưa có WebGPU; chatbot chưa chạy được trên thiết bị này.';return;}if(this.attachments.length&&!this.visionEnabled()){this.status.textContent='Ảnh đang được giữ. Chọn mô hình Có ảnh hoặc xóa ảnh để hỏi bằng văn bản.';return;}
  const key=this.key(),thread=this.thread(key),images=this.attachments.map(a=>a.url),snapshot=this.attachments.find(a=>a.context),context=this.q('#aiContext').checked?(snapshot?{...snapshot.context,snapshot:true}:this.getContext?.()||null):null,history=thread.slice(-6).map(m=>({...m}));this.busy=true;this.controller=new AbortController();this.streaming={key,question:question||'Giải thích ảnh thí nghiệm.',images,content:''};const streamState=this.streaming;this.render();let error='',result;try{this.prepareAI?.();result=await this.localAI.generate({question,history,context,images,signal:this.controller.signal,onDelta:content=>{if(this.streaming!==streamState)return;streamState.content=content;if(this.key()===key)this.render();}});}catch(e){error=e.name==='AbortError'?'Đã dừng trả lời.':e.message||'Không tạo được câu trả lời.';}finally{const partial=this.streaming?.content;this.streaming=null;this.busy=false;this.controller=null;if(result||partial){thread.push({role:'user',content:question||'Giải thích ảnh thí nghiệm.',images},{role:'assistant',content:result?.answer||partial+(error?'\n[Đã dừng]':'')});if(thread.length>30)thread.splice(0,thread.length-30);for(const old of thread.slice(0,-6))delete old.images;if(this.key()===key){this.input.value='';this.attachments=[];}else this.drafts.delete(key);}this.render();if(error)this.status.textContent=error;else if(result?.truncated)this.status.textContent='Đã tới giới hạn độ dài. Bạn có thể hỏi tiếp.';else if(this.key()!==key)this.status.textContent='Câu trả lời đã lưu trong hội thoại của bài trước.';}}
 async compress(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Chọn ảnh PNG, JPEG hoặc WebP.');if(file.size>12000000)throw Error('Ảnh tối đa 12 MB.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>32000000)throw Error('Ảnh quá lớn. Hãy cắt vùng cần hỏi.');const canvas=this.document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const url=canvas.toDataURL('image/jpeg',.82);if(url.length>1900000)throw Error('Ảnh vẫn quá lớn. Hãy cắt vùng cần hỏi.');return url;}finally{bitmap.close();}}
 async addFiles(files){if(this.busy||this.loading||this.preparing)return;if(this.local&&!this.visionEnabled()){this.status.textContent='Chọn mô hình Có ảnh trước khi thêm ảnh.';return;}const key=this.key();this.preparing++;this.render();let error='';try{for(const file of files){if(this.attachments.length>=(this.local?1:2))throw Error('Đã đủ số ảnh cho một câu hỏi.');const url=await this.compress(file);if(this.key()!==key)throw Error('Bạn đã chuyển bài. Hãy thêm ảnh vào bài đang mở.');this.attachments.push({url,name:file.name||'Ảnh dán'});}}catch(e){error=e.message||'Không đọc được ảnh.';}finally{this.preparing--;this.render();if(error)this.status.textContent=error;}}
 async captureModel(){if(this.busy||this.loading||this.preparing||!this.capture)return;if(this.local&&!this.visionEnabled()){this.status.textContent='Chọn mô hình Có ảnh trước khi chụp.';return;}this.preparing++;this.render();let error='';try{if(this.attachments.length>=(this.local?1:2))throw Error('Đã đủ số ảnh cho một câu hỏi.');const key=this.key(),result=await this.capture();if(!result?.image)throw Error('Chưa có mô hình để chụp.');const blob=await (await fetch(result.image)).blob(),url=await this.compress(blob);if(this.key()!==key)throw Error('Bạn đã chuyển bài. Hãy chụp lại mô hình.');this.attachments.push({url,name:'Mô hình '+(result.context?.title||''),context:result.context});this.q('#aiContext').checked=true;}catch(e){error=e.message||'Không chụp được mô hình.';}finally{this.preparing--;this.render();this.status.textContent=error||'Đã thêm ảnh mô hình và thông số tại thời điểm chụp. Bấm Gửi để hỏi.';}}
 async send(){if(this.local)return this.sendLocal();const question=this.input.value.trim();if((!question&&!this.attachments.length)||this.busy||this.preparing||!this.endpoint)return;const key=this.key(),thread=this.thread(key),attachments=[...this.attachments],images=attachments.map(a=>a.url),capture=attachments.find(a=>a.context),context=this.q('#aiContext').checked?(capture?{...capture.context,snapshot:true}:this.getContext?.()||null):null;
  const history=thread.slice(-10).map(m=>({role:m.role,content:m.content,images:[...(m.images||[])]}));let kept=images.length;for(let i=history.length-1;i>=0;i--){history[i].images=history[i].images.slice(0,Math.max(0,4-kept));kept+=history[i].images.length;}while(JSON.stringify({question,history,context,images}).length>4400000&&history.length)history.shift();
  this.busy=true;this.controller=new AbortController();this.render();const controller=this.controller,timeout=setTimeout(()=>controller.abort(),60000);
  try{const response=await this.fetcher(this.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history,context,images}),signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});let data;try{data=await response.json();}catch{throw Error('Máy chủ chưa sẵn sàng hoặc yêu cầu đăng nhập.');}if(!response.ok)throw Error(data.error||'Chưa gửi được câu hỏi.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('Máy chủ chưa trả về câu trả lời.');thread.push({role:'user',content:question||'Giải thích ảnh thí nghiệm.',images},{role:'assistant',content:data.answer.slice(0,16000)});if(thread.length>40)thread.splice(0,thread.length-40);for(const old of thread.slice(0,-10))delete old.images;if(this.key()===key){this.input.value='';this.attachments=[];}else this.drafts.delete(key);this.busy=false;this.render();if(this.key()!==key)this.status.textContent='Đã lưu câu trả lời trong hội thoại của bài trước.';
  }catch(error){this.busy=false;this.render();this.status.textContent=error.name==='AbortError'?'Đã dừng chờ phản hồi. Câu hỏi và ảnh vẫn được giữ.':error.message||'Không kết nối được trợ lý. Kiểm tra mạng và thử lại.';}
  finally{clearTimeout(timeout);this.controller=null;}
 }
}
